function p = HS16()
% HS16: generated by bench/corpus/generate.py from the SymPy definition. Do not edit.
% source: Hock & Schittkowski 1981; local method from x0 reaches f=3.98206 (verified local minimum)
p.name = 'HS16'; p.family = 'hs'; p.n = 2; p.m = 2;
p.x0 = [-2.0; 1.0];
p.xl = [-2.0; -Inf]; p.xu = [0.5; 1.0];
p.cl = [0.0; 0.0]; p.cu = [Inf; Inf];
p.ref_f = 0.25;
p.checksum = '3dec97aaa32a5787';
p.f = @HS16_f; p.grad = @HS16_g; p.c = @HS16_c; p.jac = @HS16_J;
